import {missions,WATER_LAB_URL} from './science-content.mjs';
import {startScience,resumeScience,currentScience,setPrediction,toggleObservation,setScienceReading,advanceScience,scienceBack,scienceFrame,openScienceExplanation,noteScienceExternal,stayScienceLocal,missionById} from './science-core.mjs';
import {guideRail} from './garden-ui.mjs';
import {portrait} from './companions.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// App initialization validates the extension. Rendering does not call an initializer.
const current=s=>s.science?.visits?.find(v=>v.id===s.science.current)||null;
const button=(attr,label,style='secondary',extra='')=>`<button type="button" class="${style}" ${attr} ${extra}>${label}</button>`;
const stageNames={wonder:'An idea to explore',explore:'Try Marble’s water simulator',notice:'Your noticing slip',explain:'Pictures to think with',ending:'An idea to take with you'};
const reading=[['unobserved','Reading not observed'],['together','Read together'],['independent','Reported read independently']];
function droplet(){return '<svg viewBox="0 0 160 145" aria-hidden="true"><ellipse cx="80" cy="124" rx="65" ry="11" fill="#abc4da" opacity=".5"/><path d="M80 9C66 34 39 57 39 82a41 41 0 0 0 82 0C121 57 94 34 80 9Z" fill="#abc4da" stroke="#183f39" stroke-width="2"/><path d="M59 67q-12 18-5 30" stroke="#fffef9" stroke-width="8" stroke-linecap="round" fill="none"/><path d="M36 133q44-8 88 0" stroke="#397958" stroke-width="2" fill="none"/></svg>';}
function heading(title,body){return `<header class="science-heading"><a href="#home" class="back">← Take a break</a><p class="science-eyebrow">Water Lab</p><h1>${esc(title)}</h1><p>${esc(body)}</p></header>`;}
function missionButtons(){return missions.map(m=>`<article class="science-mission"><div class="science-mission-mark" aria-hidden="true">${{melt:'❄',warm:'↗',evaporate:'↑'}[m.id]}</div><div><h2>${esc(m.title)}</h2><p>${esc(m.invitation)}</p>${button(`data-science-mission="${m.id}"`,'Explore this mission','primary')}</div></article>`).join('');}
export function scienceHome(state,pending){
 const x=current(state),want=missionById(pending),waiting=x&&!x.completed,m=waiting?missionById(x.missionId):null;
 const confirmation=want&&waiting&&x.missionId!==want.id?`<section class="science-decision" aria-labelledby="science-switch-title"><h2 id="science-switch-title">A mission is waiting</h2><p>You were exploring “${esc(m.title)}.” Continue it, or begin “${esc(want.title)}” and keep the earlier visit in this notebook.</p><div class="science-controls">${button(`data-science-resume="${esc(x.id)}"`,'Continue the waiting visit','primary')}${button(`data-science-start="${want.id}"`,'Begin the new mission')}</div></section>`:'';
 const visits=state.science?.visits||[];
 return `<div data-science-view class="science-view">${heading('After the storm: follow the water','The low garden path flooded. Where will the water go, and what can help us understand the garden as it dries?')}<div class="science-layout"><section class="science-notebook science-hub"><div class="science-hub-opening">${droplet()}<p>Pip and Dot are following the stormwater while the neighbors rebuild. Water can flow downhill, soak into the ground, or join the air. Today, look up close at melting, warming and evaporation. Our pictures are always here, even if you stay in the garden.</p></div><section class="science-talk"><h2>One storm, several water stories</h2><p>Did the stormwater run down the hill, soak into a garden bed, or join the air? Let’s follow one part of its story.</p><p><strong>A recovery idea to sketch:</strong> draw a hill, the flooded path and a garden bed. Where might water collect? Where could it flow or soak in? Mark your ideas with arrows and question marks.</p><p class="tiny">An optional paper investigation: draw or tell your idea together.</p><details><summary>Grown-ups: water’s possible routes</summary><p>A shrinking puddle does not tell us by itself where all its water went. The tiny-view missions explain changes inside water; they do not test a drain, a flood barrier or whether a path is ready to use. Drainage and flood-barrier experiments remain a future investigation. This paper activity needs no real floodwater. These visits are guided learning, not a test.</p><p>These stormwater connections follow <a href="https://www.usgs.gov/water-science-school/science/runoff-surface-and-overland-water-runoff" target="_blank" rel="noopener noreferrer">USGS guidance on runoff</a> and <a href="https://www.usgs.gov/water-science-school/science/evaporation-and-water-cycle" target="_blank" rel="noopener noreferrer">evaporation</a>. The local molecule pictures are explanatory drawings, not a drainage simulation.</p></details></section>${confirmation}<section class="science-decision evidence-entry"><h2>Water Evidence Shelf</h2><p>Look at three made-up before-and-after pictures. Name what you can see, then choose a careful possible explanation.</p><a class="primary" href="#science/evidence">Look at the Water Evidence Shelf</a></section><section class="science-decision cold-window-entry"><h2>Cold Window, Same Water</h2><p>Cool a made-up pane and compare invisible water vapor in the air with liquid drops on its air-facing side. No real equipment is needed.</p><a class="primary" href="#science/window">Try the cold-window picture</a></section><div class="science-missions">${missionButtons()}</div>${visits.length?`<section class="science-visits"><h2>Your notebook visits</h2><p class="tiny">An earlier visit keeps its place when you begin another.</p><ul>${[...visits].reverse().map(v=>`<li><div><strong>${esc(missionById(v.missionId).title)}</strong><span>${v.completed?'Reached an ending':'Waiting at: '+esc(stageNames[v.stage])}</span></div>${button(`data-science-resume="${esc(v.id)}"`,v.completed?'Review this visit':'Continue','secondary')}</li>`).join('')}</ul></section>`:''}</section>${guideRail(state,'{guide} says, “We can look at one thing at a time. You can change your mind, skip a step, or stop whenever you like.”')}</div><p class="tiny science-footnote">Everything here is pictures and pretend. You need no real heating, ice or equipment.</p></div>`;
}
function arrow(x,y,dx,dy,color='#397958',double=false){
 const length=Math.hypot(dx,dy)||1,ux=dx/length,uy=dy/length,head=(a,b,sign)=>`${a},${b} ${a-sign*ux*4-uy*2.5},${b-sign*uy*4+ux*2.5} ${a-sign*ux*4+uy*2.5},${b-sign*uy*4-ux*2.5}`;
 return `<path d="M${x} ${y}l${dx} ${dy}" stroke="${color}" stroke-width="1.8"/><polygon points="${head(x+dx,y+dy,1)}" fill="${color}"/>${double?`<polygon points="${head(x,y,-1)}" fill="${color}"/>`:''}`;
}
const liquid=[[69,86],[95,80],[123,88],[150,79],[77,109],[103,106],[132,112],[157,103],[65,134],[94,130],[122,137],[151,130]];
function moleculePicture(model,phase){
 const ice=model==='ice',evaporate=model==='evaporate',hot=model==='heat'&&phase>0;
 let points=ice?[...Array.from({length:6},(_,i)=>[70+32*Math.cos(i*Math.PI/3),99+32*Math.sin(i*Math.PI/3)]),...Array.from({length:6},(_,i)=>[156+32*Math.cos(i*Math.PI/3),99+32*Math.sin(i*Math.PI/3)])]:liquid.map(([x,y],i)=>[x+(model==='heat'&&phase>0?(i%3-1)*4:0),y+(model==='heat'&&phase>0?(i%2?3:-3):0)]);
 if(ice&&phase===1)points=points.map(([x,y],i)=>[x+(i%2?2:-2),y+(i%2?-2:2)]);
 if(evaporate)points[0]=[69,phase===0?86:phase===1?58:27];
 const alt=ice?'Twelve same-sized molecule dots in two open hexagonal patterns, with short back-and-forth vibration arrows.':evaporate?`Twelve same-sized water molecule dots. The ringed molecule is ${phase===0?'at the liquid surface':phase===1?'moving out above the surface':'in the air as water vapor'}; the other eleven remain in liquid.`:`Twelve same-sized water molecule dots in a closer, irregular liquid arrangement. ${hot?'Longer':'Short'} arrows represent molecular motion.`;
 const drawing=points.map(([x,y],i)=>{
  let motion;if(ice)motion=arrow(x-4,y-12,8,0,'#397958',true);
  else if(evaporate&&i===0)motion=phase===0?arrow(x+12,y,0,-13):arrow(x+12,y+7,0,-19);
  else{const d=hot?16:model==='water'?11:6,angle=(i*1.7)+.4;motion=arrow(x+10,y-7,Math.cos(angle)*d,Math.sin(angle)*d);}
  return `${motion}<circle cx="${x}" cy="${y}" r="6" fill="#abc4da" stroke="#183f39" stroke-width="1.5"/>${evaporate&&i===0?`<circle cx="${x}" cy="${y}" r="10" fill="none" stroke="#9b6325" stroke-width="2"/>`:''}`;
 }).join('');
 const pattern=ice?[70,156].map(cx=>`<polygon points="${Array.from({length:6},(_,i)=>`${cx+32*Math.cos(i*Math.PI/3)},${99+32*Math.sin(i*Math.PI/3)}`).join(' ')}" fill="none" stroke="#8aa8a1" stroke-dasharray="3 4"/>`).join(''):'';
 return `<svg viewBox="0 0 240 180" role="img" aria-label="${esc(alt)}"><rect x="12" y="12" width="216" height="155" rx="12" fill="#fffef9" stroke="#8aa8a1"/>${!ice?`<path d="M20 78H220V158H20Z" fill="#e3eef3"/>${evaporate?'<path d="M20 78H220" stroke="#397958" stroke-dasharray="4 3"/>':''}`:''}${pattern}${drawing}</svg>`;
}
function wholePicture(model,phase){
 const ice=model==='ice',evap=model==='evaporate',warm=model==='heat'&&phase>0;
 const alt=ice?'An original drawing of a solid ice block in a glass.':evap?'A glass still containing liquid water. An upward arrow marks evaporation, not visible vapor.':warm?'An original drawing of warmer liquid water in a glass.':'An original drawing of liquid water in a glass.';
 return `<svg viewBox="0 0 240 180" role="img" aria-label="${esc(alt)}"><ellipse cx="113" cy="162" rx="85" ry="9" fill="#abc4da" opacity=".35"/>${ice?'<path d="M68 75l50-18 41 23-50 19Z" fill="#dceaf2" stroke="#397958"/><path d="M68 75v47l41 25V99Z" fill="#abc4da" stroke="#397958"/><path d="M109 99l50-19v45l-50 22Z" fill="#c8dce7" stroke="#397958"/>':'<path d="M54 83Q111 71 173 83L164 147H64Z" fill="#abc4da"/><path d="M54 83Q111 95 173 83" fill="none" stroke="#397958" stroke-width="2"/>'}<path d="M44 33L60 150Q112 164 168 150L185 33" fill="none" stroke="#183f39" stroke-width="3"/><ellipse cx="114" cy="33" rx="70" ry="10" fill="none" stroke="#183f39" stroke-width="2"/>${model==='heat'?`<path d="M210 44v91" stroke="#52675e" stroke-width="11" stroke-linecap="round"/><path d="M210 ${warm?52:105}v${warm?83:30}" stroke="#b65c4a" stroke-width="5" stroke-linecap="round"/><circle cx="210" cy="143" r="11" fill="#b65c4a"/>`:''}${evap&&phase>0?arrow(110,62,0,-39,'#397958'):''}</svg>`;
}
function frameView(m,x){
 const f=m.frames[x.frame];
 const macro=f.model==='ice'?'Solid ice':f.model==='evaporate'?'Liquid stays below. Water vapor is invisible.':f.model==='heat'?(f.phase===0?'Cooler liquid':'Warmer liquid'):'Liquid water';
 return `<section class="science-explanation" aria-labelledby="science-frame-title"><div class="science-frame-heading"><span>Picture ${x.frame+1} of ${m.frames.length}</span><h3 id="science-frame-title" tabindex="-1">${esc(f.title)}</h3></div><div class="science-picture-pair"><figure><h4>The whole glass</h4>${wholePicture(f.model,f.phase)}<figcaption>${macro}</figcaption></figure><figure><h4>An imagined tiny view</h4>${moleculePicture(f.model,f.phase)}<figcaption>${f.model==='ice'?'Short two-way arrows: vibration':f.model==='evaporate'?'Ring: the molecule we are following':'Arrows: molecular motion'}</figcaption></figure></div><p class="science-frame-body">${esc(f.body)}</p><p class="tiny science-model-label">These are drawings of things too tiny to see. Each dot is one water molecule.</p><div class="science-frame-controls">${button('data-science-frame="-1"','<span aria-hidden="true">←</span> Previous picture','secondary',x.frame===0?'disabled':'')}${button('data-science-frame="1"','Next picture <span aria-hidden="true">→</span>','secondary',x.frame===m.frames.length-1?'disabled':'')}${button('data-science-frame="reset"','Start pictures again','text-button')}</div>${m.id==='melt'?'<p><a class="primary" href="#science/ice">Try Ice and warmth · add or remove energy</a></p>':''}</section>`;
}
function readingView(x){return `<details class="science-reading"><summary>For grown-ups: how did we read this part?</summary><p class="tiny">Reading is a separate observation. Exploring a picture does not tell us how someone read.</p><div class="science-reading-options" role="group" aria-label="Reading observation">${reading.map(([value,label])=>button(`data-science-reading="${value}"`,label,`method ${x.reading===value?'selected':''}`,`aria-pressed="${x.reading===value}"`)).join('')}</div></details>`;}
function wonder(m,x){return `<p class="science-story">${esc(m.story)}</p><h3 class="science-question">${esc(m.predictionPrompt)}</h3><p>Choose an idea if you like. Every idea is welcome here.</p><div class="science-choices" role="group" aria-label="Optional prediction">${m.predictions.map((text,i)=>button(`data-science-prediction="${i}"`,esc(text),`science-choice ${x.prediction===i?'selected':''}`,`aria-pressed="${x.prediction===i}"`)).join('')}</div>${x.prediction!==null?`${button('data-science-prediction="clear"','Clear my idea','text-button')}`:''}`;}
function explore(m,x){return `<p class="science-story">A little trip to Marble’s water simulator</p><ol class="science-instructions">${m.instructions.map(text=>`<li>${esc(text)}</li>`).join('')}</ol><div class="science-external"><a class="primary" data-science-link href="${WATER_LAB_URL}" target="_blank" rel="noopener noreferrer">Open Marble’s water simulator <span aria-hidden="true">↗</span></a><p>It opens in another tab. Come back to this tab to keep going.</p></div>${button('data-science-local','Stay here and explore the pictures','secondary')}<p class="tiny">If the site will not open or feels confusing, you can stay here. All our pictures are here too.${x.stayedLocal?' You chose to stay with our pictures.':''}</p><details class="grownup-note"><summary>For grown-ups</summary><p>No garden answers are sent. Marble handles its own site visits. Choosing this link only records that it was selected. It does not show whether the site was visited or anything was tried.</p></details>`;}
function notice(m,x){return `<h3 class="science-question">What would you like to put on your noticing slip?</h3><p>Choose any that fit what you noticed, or leave the slip blank.</p><div class="science-choices" role="group" aria-label="What you noticed">${m.observations.map((text,i)=>button(`data-science-report="${i}"`,`${x.observations.includes(i)?'<span aria-hidden="true">✓ </span>':''}${esc(text)}`,`science-choice ${x.observations.includes(i)?'selected':''}`,`aria-pressed="${x.observations.includes(i)}"`)).join('')}</div><p class="tiny">Saying “I’m not sure” is useful too.</p><details class="grownup-note"><summary>For grown-ups</summary><p>These are the child’s own reports. The garden cannot check the other site.</p></details>`;}
function ending(m,x){return `<div class="science-ending-mark" aria-hidden="true">${droplet()}</div><p class="science-story">A good place to pause</p><p>There is always more to wonder about. You can stop here, revisit a picture, or explore another mission. Nothing has to be handed in.</p><section class="science-project"><h3>A paper or talking idea</h3><p>${esc(m.project)}</p><p class="tiny">This is optional.</p></section><div class="science-controls">${button('data-science-explanation','Review the explanation','primary')}<a class="secondary" href="#science">Choose another mission</a><a class="text-button" href="#home">Back to the garden</a></div>`;}
export function sciencePage(state){
 const x=current(state),m=x?missionById(x.missionId):null;if(!x||!m)return scienceHome(state);
 const body=x.stage==='wonder'?wonder(m,x):x.stage==='explore'?explore(m,x):x.stage==='notice'?notice(m,x):x.stage==='explain'?frameView(m,x):ending(m,x);
 const guide=x.stage==='wonder'?'{guide} says, “An idea gives us something to explore. We can change our minds.”':x.stage==='explore'?'{guide} says, “You choose: try Marble’s water simulator, or stay here with our pictures. We can take a break either way.”':x.stage==='notice'?'{guide} says, “Tell us what you noticed, or what you are not sure about. No answer is required.”':x.stage==='explain'?'{guide} says, “One picture at a time. The arrows and dots are drawings that help us explain.”':'{guide} says, “We can keep wondering later. A visit can end without an answer to everything.”';
 return `<div data-science-view class="science-view">${heading(m.title,m.invitation)}<a class="science-hub-link" href="#science">All water missions and saved visits</a><div class="science-layout"><article class="science-notebook"><div class="science-stage-label"><span>${esc(stageNames[x.stage])}${x.completed&&x.stage!=='ending'?' · Looking back at a finished visit':''}</span><span class="science-explorer">${portrait(state.garden.avatar,true)}</span></div><h2 id="science-stage-title" tabindex="-1">${esc(stageNames[x.stage])}</h2>${body}${x.stage==='explain'?`<section class="science-talk"><h3>Something to wonder</h3><p>${esc(m.talk)}</p><p class="tiny">Talk, gesture, or draw together.</p></section>`:''}${readingView(x)}${x.stage!=='ending'?`<div class="science-stage-controls">${x.stage!=='wonder'?button('data-science-back','<span aria-hidden="true">←</span> Previous step','secondary'):''}${button('data-science-next',x.stage==='explain'?'Take an idea to the ending':x.stage==='explore'?(x.externalLinkOpened?'We’re back · what did we notice?':'On to what we noticed'):x.stage==='notice'?'Look at explanation pictures':'Explore · an idea is optional','primary')}</div>${x.stage!=='explain'?button('data-science-explanation','Go straight to the explanation pictures','text-button'):''}`:button('data-science-back','<span aria-hidden="true">←</span> Back to the pictures','text-button')}<p class="tiny science-pause"><a href="#home">Take a break</a> · Your choices stay with this visit.</p><details class="science-sources"><summary>Grown-ups: sources and model limits</summary><p>These are guided learning records, not assessments. An external-link selection is not evidence of a site visit. Choices stay with this visit under the app’s current saving setting. The pictures are original explanatory drawings, not a live experiment or measurements. They simplify arrangements and movement. Sizes, spaces, arrows and times are not to scale, and longer arrows are a drawing choice rather than measured speeds.</p><ul>${m.sourceLinks.map(link=>`<li><a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer" ${link.url===WATER_LAB_URL?'data-science-link':''}>${esc(link.title)} <span aria-hidden="true">↗</span></a></li>`).join('')}</ul></details></article>${guideRail(state,guide)}</div></div>`;
}
export function scienceNotes(state){
 const visits=state.science?.visits||[];
 return `<section class="panel science-notes"><h2>Water expedition notebook</h2><p>All these visits are guided learning. Predictions and observation reports are unscored. Reports are self-reported; neither a link selection nor an ending proves a site visit, experiment, understanding, or off-screen project.</p><p class="tiny">The notebook retains up to 24 visits, including the current visit. It is not an exhaustive permanent history. Reading observations are separate from picture use or explanations.</p>${[...visits].reverse().map(x=>{
  const m=missionById(x.missionId);return `<details class="science-note-visit"><summary>${esc(m.title)}: ${x.completed?'Reached an ending':'Waiting at '+esc(stageNames[x.stage])}</summary><p><strong>Prediction:</strong> ${x.prediction===null?'Not selected':esc(m.predictions[x.prediction])}${x.prediction===null?'':x.predictionAfterTeaching?' (selected after this visit’s explanation was opened)':' (selected before this visit’s explanation was opened)'}.</p><p><strong>Reports:</strong> ${x.observations.length?x.observations.map(i=>esc(m.observations[i])).join(' / '):'None selected'}.</p><p><strong>Support/context:</strong> Explanation ${x.explanationOpened?'opened':'not opened'}; picture ${x.frame+1} currently selected. External link to Marble’s water simulator ${x.externalLinkOpened?'selected':'not selected'}; no external visit is verified. Local pictures ${x.stayedLocal?'chosen explicitly':'not chosen explicitly'}.</p><p><strong>Reading:</strong> ${x.reading==='independent'?'reported read independently':x.reading==='together'?'read together':'not observed'}.</p>${button(`data-science-resume="${esc(x.id)}"`,'Return to this visit','secondary')}</details>`;
 }).join('')||'<p>No water expedition visits yet.</p>'}<a href="#science">Open the Water Lab</a></section>`;
}
export function bindScience(state,{save,render,focus}){
 // Notes also have resume controls, but no science renderer mutates or starts a visit.
 const roots=[...document.querySelectorAll('[data-science-view],.science-notes')];if(!roots.length)return;
 const redraw=selector=>{save();render();if(selector)focus(selector);};
 const navigate=hash=>{save();if(window.location.hash===hash){render();focus('#science-stage-title');}else window.location.hash=hash;};
 for(const root of roots){
  root.querySelectorAll('[data-science-mission]').forEach(el=>el.addEventListener('click',()=>{
   const m=missionById(el.dataset.scienceMission);if(!m)return;const x=currentScience(state);
   if(x&&!x.completed){if(x.missionId===m.id)navigate('#science/play');else navigate('#science/choose/'+m.id);return;}
   if(startScience(state,m.id))navigate('#science/play');
  }));
  root.querySelectorAll('[data-science-start]').forEach(el=>el.addEventListener('click',()=>{if(startScience(state,el.dataset.scienceStart))navigate('#science/play');}));
  root.querySelectorAll('[data-science-resume]').forEach(el=>el.addEventListener('click',()=>{resumeScience(state,el.dataset.scienceResume);if(currentScience(state)?.id===el.dataset.scienceResume)navigate('#science/play');}));
  root.querySelectorAll('[data-science-prediction]').forEach(el=>el.addEventListener('click',()=>{const value=el.dataset.sciencePrediction;setPrediction(state,value==='clear'?null:Number(value));redraw(value==='clear'?'#science-stage-title':`[data-science-prediction="${value}"]`);}));
  root.querySelectorAll('[data-science-report]').forEach(el=>el.addEventListener('click',()=>{toggleObservation(state,Number(el.dataset.scienceReport));redraw(`[data-science-report="${el.dataset.scienceReport}"]`);}));
  root.querySelectorAll('[data-science-reading]').forEach(el=>el.addEventListener('click',()=>{setScienceReading(state,el.dataset.scienceReading);redraw(`[data-science-reading="${el.dataset.scienceReading}"]`);}));
  root.querySelectorAll('[data-science-frame]').forEach(el=>el.addEventListener('click',()=>{scienceFrame(state,el.dataset.scienceFrame==='reset'?'reset':Number(el.dataset.scienceFrame));redraw('#science-frame-title');}));
  root.querySelectorAll('[data-science-next]').forEach(el=>el.addEventListener('click',()=>{advanceScience(state);redraw('#science-stage-title');}));
  root.querySelectorAll('[data-science-back]').forEach(el=>el.addEventListener('click',()=>{scienceBack(state);redraw('#science-stage-title');}));
  root.querySelectorAll('[data-science-explanation]').forEach(el=>el.addEventListener('click',()=>{openScienceExplanation(state);redraw('#science-stage-title');}));
  root.querySelectorAll('[data-science-local]').forEach(el=>el.addEventListener('click',()=>{stayScienceLocal(state);openScienceExplanation(state);redraw('#science-stage-title');}));
  root.querySelectorAll('[data-science-link]').forEach(el=>el.addEventListener('click',()=>{noteScienceExternal(state);save();}));
 }
}
